//! Demo mode (`TG_DEMO=1`): renders the real interface from seed data, with
//! no TDLib client and no account. Used for design work and screenshots.
//!
//! TDLib types have no serde defaults, so `demo/defaults.json` (generated by
//! `scripts/demo_defaults.py`) holds a complete default object per type and
//! the seed patches the fields it cares about.

use std::sync::LazyLock;

use anyhow::{Context, Result};
use chrono::{Duration, Local, Timelike};
use serde::de::DeserializeOwned;
use serde_json::{Value, json};
use tdlib_rs::types::{Chat, ChatFolderInfo, ChatPhoto, Message, Sticker, User};

pub fn enabled() -> bool {
    std::env::var_os("TG_DEMO").is_some()
}

/// Which screen to open first, for screenshots: `chat`, `group`, `details`,
/// `palette`, `menu`, `viewer`, `channel`, `archive`, `login`, `list`.
pub fn scene() -> String {
    std::env::var("TG_DEMO_SCENE").unwrap_or_else(|_| "chat".into())
}

/// `TG_DEMO_THEME=light|dark` overrides the system appearance.
pub fn theme() -> Option<bool> {
    if !enabled() {
        return None;
    }
    match std::env::var("TG_DEMO_THEME").ok()?.as_str() {
        "light" => Some(true),
        "dark" => Some(false),
        _ => None,
    }
}

pub struct Seed {
    pub me: i64,
    pub users: Vec<User>,
    pub chats: Vec<(Chat, Vec<Message>)>,
    pub folders: Vec<ChatFolderInfo>,
    /// (group id, member count, is channel)
    pub groups: Vec<(i64, i32, bool)>,
    pub pinned: Vec<(i64, Vec<Message>)>,
    /// Profile photos per chat, newest first.
    pub profile_photos: Vec<(i64, Vec<ChatPhoto>)>,
    pub stickers: Vec<Sticker>,
}

