static DEFAULTS: LazyLock<Value> = LazyLock::new(|| {
    serde_json::from_str(include_str!("demo/defaults.json")).unwrap_or(Value::Null)
});

fn template(path: &[&str]) -> Value {
    path.iter()
        .fold(&*DEFAULTS, |value, key| &value[*key])
        .clone()
}

fn merge(base: &mut Value, patch: Value) {
    match (base, patch) {
        (Value::Object(base), Value::Object(patch)) => {
            for (key, value) in patch {
                merge(base.entry(key).or_insert(Value::Null), value);
            }
        }
        (base, patch) => *base = patch,
    }
}

fn patched(path: &[&str], patch: Value) -> Value {
    let mut value = template(path);
    merge(&mut value, patch);
    value
}

fn build<T: DeserializeOwned>(path: &[&str], patch: Value) -> Result<T> {
    serde_json::from_value(patched(path, patch)).with_context(|| format!("demo seed {path:?}"))
}

fn variant(kind: &str, name: &str, patch: Value) -> Value {
    patched(&["variants", kind, name], patch)
}

fn asset(name: &str) -> String {
    format!("{}/assets/{name}", env!("CARGO_MANIFEST_DIR"))
}

/// A downloaded local file.
fn file(id: i32, name: &str) -> Value {
    let path = asset(name);
    let size = std::fs::metadata(&path).map_or(0, |m| m.len() as i64);
    patched(
        &["File"],
        json!({
            "id": id,
            "size": size,
            "expected_size": size,
            "local": {
                "path": path,
                "can_be_downloaded": true,
                "is_downloading_completed": true,
                "downloaded_size": size,
            },
        }),
    )
}

/// Unix time `days` ago at `hour:minute` local time.
fn at(days: i64, hour: u32, minute: u32) -> i32 {
    let day = Local::now() - Duration::days(days);
    day.with_hour(hour)
        .and_then(|t| t.with_minute(minute))
        .map_or(0, |t| t.timestamp() as i32)
}

fn formatted(text: &str, entities: &[(usize, usize, &str, Value)]) -> Value {
    // Offsets here are in UTF-16 units, as TDLib expects.
    let entities: Vec<Value> = entities
        .iter()
        .map(|(offset, length, kind, extra)| {
            json!({
                "offset": offset,
                "length": length,
                "type": variant("TextEntityType", kind, extra.clone()),
            })
        })
        .collect();
    json!({ "text": text, "entities": entities })
}

fn text(body: &str) -> Value {
    patched(
        &["content", "MessageText"],
        json!({ "text": formatted(body, &[]) }),
    )
}

fn rich(body: &str, entities: &[(usize, usize, &str, Value)]) -> Value {
    patched(
        &["content", "MessageText"],
        json!({ "text": formatted(body, entities) }),
    )
}

fn photo(file_id: i32, name: &str, width: i32, height: i32, caption: &str) -> Value {
    patched(
        &["content", "MessagePhoto"],
        json!({
            "photo": {
                "sizes": [patched(&["PhotoSize"], json!({
                    "type": "y",
                    "photo": file(file_id, name),
                    "width": width,
                    "height": height,
                }))],
            },
            "caption": formatted(caption, &[]),
        }),
    )
}

fn sticker_value(id: i64, file_id: i32, name: &str, emoji: &str) -> Value {
    patched(
        &["Sticker"],
        json!({
            "id": id.to_string(),
            "set_id": "1",
            "width": 512,
            "height": 512,
            "emoji": emoji,
            "format": variant(
                "StickerFormat",
                if name.ends_with(".tgs") { "Tgs" } else { "Webp" },
                json!({}),
            ),
            "sticker": file(file_id, name),
        }),
    )
}

fn sticker(id: i64, file_id: i32, name: &str, emoji: &str) -> Value {
    patched(
        &["content", "MessageSticker"],
        json!({ "sticker": sticker_value(id, file_id, name, emoji) }),
    )
}

/// TDLib's waveform: 5-bit samples packed little-endian, base64-encoded.
fn waveform(samples: &[u8]) -> String {
    let mut bytes = vec![0u8; (samples.len() * 5).div_ceil(8) + 1];
    for (index, sample) in samples.iter().enumerate() {
        let bit = index * 5;
        let value = u16::from(*sample & 0x1f) << (bit % 8);
        bytes[bit / 8] |= value as u8;
        bytes[bit / 8 + 1] |= (value >> 8) as u8;
    }
    const TABLE: &[u8; 64] = b"ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/";
    let mut out = String::new();
    for chunk in bytes.chunks(3) {
        let n = (u32::from(chunk[0]) << 16)
            | (u32::from(*chunk.get(1).unwrap_or(&0)) << 8)
            | u32::from(*chunk.get(2).unwrap_or(&0));
        for i in 0..4 {
            if i <= chunk.len() {
                out.push(TABLE[(n >> (18 - 6 * i) & 63) as usize] as char);
            } else {
                out.push('=');
            }
        }
    }
    out
}

fn voice(file_id: i32, duration: i32) -> Value {
    let samples: Vec<u8> = (0..60)
        .map(|i| {
            let x = i as f32 / 60. * std::f32::consts::TAU * 3.;
            (8. + 12. * x.sin().abs() + 6. * (x * 2.7).cos().abs()).min(31.) as u8
        })
        .collect();
    patched(
        &["content", "MessageVoiceNote"],
        json!({
            "voice_note": {
                "duration": duration,
                "waveform": waveform(&samples),
                "mime_type": "audio/ogg",
                "voice": file(file_id, "demo/voice.oga"),
            },
        }),
    )
}

fn round_video(file_id: i32, thumb_id: i32, duration: i32) -> Value {
    patched(
        &["content", "MessageVideoNote"],
        json!({
            "video_note": {
                "duration": duration,
                "length": 384,
                "thumbnail": {
                    "format": { "@type": "thumbnailFormatPng" },
                    "width": 320,
                    "height": 320,
                    "file": file(thumb_id, "demo/avatar-lake.png"),
                },
                "video": file(file_id, "demo/round.mp4"),
            },
        }),
    )
}

fn document(file_id: i32, name: &str, shown: &str) -> Value {
    patched(
        &["content", "MessageDocument"],
        json!({
            "document": {
                "file_name": shown,
                "mime_type": "application/pdf",
                "document": file(file_id, name),
            },
        }),
    )
}

fn poll(question: &str, options: &[(&str, i32, bool)]) -> Value {
    let total: i32 = options.iter().map(|o| o.1).sum();
    let options: Vec<Value> = options
        .iter()
        .map(|(label, votes, chosen)| {
            patched(
                &["PollOption"],
                json!({
                    "text": formatted(label, &[]),
                    "voter_count": votes,
                    "vote_percentage": if total > 0 { votes * 100 / total } else { 0 },
                    "is_chosen": chosen,
                }),
            )
        })
        .collect();
    patched(
        &["content", "MessagePoll"],
        json!({
            "poll": patched(&["Poll"], json!({
                "id": "1",
                "question": formatted(question, &[]),
                "options": options,
                "total_voter_count": total,
                "is_anonymous": false,
                "type": variant("PollType", "Regular", json!({ "allow_multiple_answers": false })),
            })),
        }),
    )
}

fn reactions(list: &[(&str, i32, bool)]) -> Value {
    let reactions: Vec<Value> = list
        .iter()
        .map(|(emoji, count, chosen)| {
            patched(
                &["MessageReaction"],
                json!({
                    "type": variant("ReactionType", "Emoji", json!({ "emoji": emoji })),
                    "total_count": count,
                    "is_chosen": chosen,
                }),
            )
        })
        .collect();
    patched(
        &["MessageInteractionInfo"],
        json!({ "reactions": patched(&["MessageReactions"], json!({ "reactions": reactions })) }),
    )
}

struct Msg {
    id: i64,
    from: i64,
    date: i32,
    content: Value,
    extra: Value,
}

fn msg(id: i64, from: i64, date: i32, content: Value) -> Msg {
    Msg {
        id,
        from,
        date,
        content,
        extra: json!({}),
    }
}

impl Msg {
    fn with(mut self, patch: Value) -> Self {
        merge(&mut self.extra, patch);
        self
    }

    fn build(self, chat_id: i64) -> Result<Message> {
        let mut value = patched(
            &["Message"],
            json!({
                "id": self.id,
                "chat_id": chat_id,
                "sender_id": variant("MessageSender", "User", json!({ "user_id": self.from })),
                "is_outgoing": self.from == ME,
                "date": self.date,
                "content": self.content,
            }),
        );
        merge(&mut value, self.extra);
        serde_json::from_value(value).context("demo message")
    }
}

fn user(
    id: i64,
    first: &str,
    last: &str,
    status: Value,
    photo: Option<(i32, &str)>,
) -> Result<User> {
    build(
        &["User"],
        json!({
            "id": id,
            "first_name": first,
            "last_name": last,
            "phone_number": "15550100",
            "status": status,
            "usernames": {
                "active_usernames": [first.to_lowercase()],
                "disabled_usernames": [],
                "editable_username": first.to_lowercase(),
                "collectible_usernames": [],
            },
            "profile_photo": photo.map(|(file_id, name)| patched(&["ProfilePhoto"], json!({
                "id": "1",
                "small": file(file_id, name),
                "big": file(file_id + 1, name),
            }))),
            "type": { "@type": "userTypeRegular" },
        }),
    )
}

struct ChatSpec<'a> {
    id: i64,
    title: &'a str,
    kind: Value,
    photo: Option<(i32, &'a str)>,
    order: i64,
    pinned: bool,
    archived: bool,
    folders: &'a [i32],
    muted: bool,
    unread: i32,
    last_read_inbox: i64,
}

fn chat(spec: ChatSpec, messages: Vec<Msg>) -> Result<(Chat, Vec<Message>)> {
    let messages: Vec<Message> = messages
        .into_iter()
        .map(|m| m.build(spec.id))
        .collect::<Result<_>>()?;
    let last = messages.last().map(serde_json::to_value).transpose()?;
    let list = if spec.archived { "Archive" } else { "Main" };
    let mut positions = vec![patched(
        &["ChatPosition"],
        json!({
            "list": variant("ChatList", list, json!({})),
            "order": spec.order.to_string(),
            "is_pinned": spec.pinned,
        }),
    )];
    for folder in spec.folders {
        positions.push(patched(
            &["ChatPosition"],
            json!({
                "list": variant("ChatList", "Folder", json!({ "chat_folder_id": folder })),
                "order": spec.order.to_string(),
            }),
        ));
    }
    let last_outbox = messages.iter().map(|m| m.id).max().unwrap_or(0);
    let info: Chat = build(
        &["Chat"],
        json!({
            "id": spec.id,
            "type": spec.kind,
            "title": spec.title,
            "photo": spec.photo.map(|(file_id, name)| patched(&["ChatPhotoInfo"], json!({
                "small": file(file_id, name),
                "big": file(file_id + 1, name),
            }))),
            "last_message": last,
            "positions": positions,
            "unread_count": spec.unread,
            "last_read_inbox_message_id": spec.last_read_inbox,
            "last_read_outbox_message_id": last_outbox,
            "notification_settings": { "mute_for": if spec.muted { i32::MAX } else { 0 } },
            "permissions": { "can_send_basic_messages": true },
        }),
    )?;
    Ok((info, messages))
}

fn private(user_id: i64) -> Value {
    variant("ChatType", "Private", json!({ "user_id": user_id }))
}

